INSERT INTO film_reviews (filmID, filmtitle, releasedate, rating, review) VALUES (1, 'Casablanca', '1942-11-26', 10, 'A wonderfully romantic wartime drama that has lost none of its charm. Humphrey Bogart is the epitome of weary cool, Ingrid Bergman is luminous, and the dialogue is endlessly quotable. The Moroccan setting is vividly atmospheric, and the supporting cast is superb. It remains a model of classic Hollywood storytelling.');
INSERT INTO film_reviews (filmID, filmtitle, releasedate, rating, review) VALUES (2, 'The Godfather', '1972-03-24', 10, 'A masterclass in patient storytelling. Brando and Pacino anchor a family saga where every quiet conversation carries menace. The photography is rich and shadowy, the pacing deliberate, and the moral slide of Michael Corleone feels tragic rather than glamorous. Decades on, it still sets the standard for crime drama. Memorable.');
INSERT INTO film_reviews (filmID, filmtitle, releasedate, rating, review) VALUES (3, 'Jaws', '1975-06-20', 9, 'Spielberg proves that what you don''t see can be scarier than what you do. The mechanical shark barely appears, yet the score and clever editing keep tension high. Funny, human and expertly paced, it works as both a monster movie and a wonderful character study about three men. Worth seeing.');
INSERT INTO film_reviews (filmID, filmtitle, releasedate, rating, review) VALUES (4, 'Star Wars', '1977-05-25', 9, 'A fairy tale dressed in spaceships that still feels thrillingly fresh. The characters are instantly lovable, the effects have charm, and the story moves at a joyful gallop. Some dialogue is clunky, but the sense of wonder and John Williams''s soaring music more than compensate. Many viewers remember it fondly.');
INSERT INTO film_reviews (filmID, filmtitle, releasedate, rating, review) VALUES (5, 'Alien', '1979-05-25', 9, 'Claustrophobic, slow-burning and gorgeously designed, this haunted house in space gets under your skin. The cast feels like real tired workers, the creature is unforgettable, and Ridley Scott withholds information masterfully. Sigourney Weaver emerges as a heroine whose resourcefulness makes the final act genuinely nail-biting. Many viewers remember it fondly.');
INSERT INTO film_reviews (filmID, filmtitle, releasedate, rating, review) VALUES (6, 'Raiders of the Lost Ark', '1981-06-12', 9, 'Pure adventure joy from start to finish. Harrison Ford''s wry, bruised hero charms throughout, while the set pieces, from the boulder chase to the truck sequence, remain gloriously inventive. It is quick, funny and beautifully staged, and it makes modern action films look fussy by comparison. Still easy to enjoy.');
INSERT INTO film_reviews (filmID, filmtitle, releasedate, rating, review) VALUES (7, 'E.T. the Extra-Terrestrial', '1982-06-11', 9, 'A gentle, heartfelt story about friendship seen through a child''s eyes. The creature design is wonderfully expressive, and the young cast feels completely natural. Spielberg balances humour, wonder and tenderness so well that the emotional ending lands every time, even for viewers who think they are too cynical. Worth seeing.');
INSERT INTO film_reviews (filmID, filmtitle, releasedate, rating, review) VALUES (8, 'Blade Runner', '1982-06-25', 9, 'A rain-soaked, neon-lit vision of the future that rewards patience. The story is simple, but the atmosphere, Vangelis''s score and Rutger Hauer''s poetic final speech elevate it into something haunting. It asks what makes us human without ever feeling preachy, and looks stunning today. It remains a popular choice today.');
INSERT INTO film_reviews (filmID, filmtitle, releasedate, rating, review) VALUES (9, 'Ghostbusters', '1984-06-08', 8, 'Loose, funny and effortlessly quotable. Bill Murray''s deadpan wit holds the chaos together while the supernatural effects still look charming. The plot is slight and the pacing occasionally wanders, but the cast chemistry and that unforgettable theme tune make it a comedy classic worth revisiting. Many viewers remember it fondly.');
INSERT INTO film_reviews (filmID, filmtitle, releasedate, rating, review) VALUES (10, 'The Breakfast Club', '1985-02-15', 8, 'Five teenagers, one library, and a surprisingly honest look at growing up. The script is talky and a little stagey, but the young cast brings real vulnerability beneath the stereotypes. It is funny, warm and occasionally painful, and its central message about labels still resonates. Many viewers remember it fondly.');
INSERT INTO film_reviews (filmID, filmtitle, releasedate, rating, review) VALUES (11, 'Back to the Future', '1985-07-03', 10, 'Almost perfectly constructed. Every setup pays off, every joke lands, and Michael J. Fox and Christopher Lloyd make a delightful double act. The time-travel logic is clever without being confusing, and the climax at the clock tower is endlessly rewatchable. Pure, joyful entertainment. Whatever your taste, it leaves an impression.');
INSERT INTO film_reviews (filmID, filmtitle, releasedate, rating, review) VALUES (12, 'Top Gun', '1986-05-16', 6, 'Slick, glossy and wildly overstuffed with swagger. The flying sequences still thrill, and the soundtrack is pure eighties gold, but the romance and dialogue are cheesy. Tom Cruise commands the screen regardless, making this an enjoyable, if shallow, slice of nostalgic popcorn entertainment. Whatever your taste, it leaves an impression.');
INSERT INTO film_reviews (filmID, filmtitle, releasedate, rating, review) VALUES (13, 'Ferris Bueller''s Day Off', '1986-06-11', 8, 'Cheeky, charming and endlessly rewatchable. Matthew Broderick speaks directly to us and makes mischief feel like a virtue. The film is lightweight, but its warmth, Chicago backdrop and surprisingly thoughtful ending about friendship and growing up make it far more than just a day off. Many viewers remember it fondly.');
INSERT INTO film_reviews (filmID, filmtitle, releasedate, rating, review) VALUES (14, 'Aliens', '1986-07-18', 9, 'James Cameron swaps horror for relentless action and somehow improves on the original in a different way. The marines are vividly sketched, the tension never lets up, and Sigourney Weaver is extraordinary. Loud, inventive and emotionally satisfying, it is one of the best sequels ever made. Still easy to enjoy.');
INSERT INTO film_reviews (filmID, filmtitle, releasedate, rating, review) VALUES (15, 'Die Hard', '1988-07-15', 9, 'The template for modern action done properly. Bruce Willis plays a flawed, barefoot everyman, while Alan Rickman''s villain is elegant and witty. The single-building setting keeps the tension tight, the stunts feel physical, and the humour never undercuts the danger. Still sharp, still thrilling. It remains a popular choice today.');
INSERT INTO film_reviews (filmID, filmtitle, releasedate, rating, review) VALUES (16, 'Rain Man', '1988-12-16', 8, 'Dustin Hoffman gives a remarkable, detailed performance, and Tom Cruise matches him with a surprisingly nuanced turn as a selfish brother slowly changing. The road-trip structure is familiar, but the relationship at its centre is genuinely moving. It is gentle, funny and quietly affecting. It remains a popular choice today.');
INSERT INTO film_reviews (filmID, filmtitle, releasedate, rating, review) VALUES (17, 'Dead Poets Society', '1989-06-02', 8, 'A warm, inspiring tale of a teacher who urges students to think for themselves. Robin Williams is charming and restrained, and the young cast is excellent. The ending is emotional and slightly manipulative, yet the autumn setting and message about seizing the day linger long afterwards. Still easy to enjoy.');
INSERT INTO film_reviews (filmID, filmtitle, releasedate, rating, review) VALUES (18, 'Batman', '1989-06-23', 7, 'Tim Burton''s gothic Gotham is a wonderfully strange place, and Jack Nicholson relishes every moment as the Joker. The plot is thin and Michael Keaton gets less screen time than expected, but the atmosphere, production design and Danny Elfman''s score are unforgettable. Many people return to it again and again.');
INSERT INTO film_reviews (filmID, filmtitle, releasedate, rating, review) VALUES (19, 'Goodfellas', '1990-09-19', 10, 'Scorsese''s kinetic gangster epic pulls you in with charm before showing the cost. The long tracking shot, the needle-drop soundtrack and the pitch-perfect performances make three hours fly by. Funny, thrilling and ultimately chilling, it is endlessly watchable and endlessly influential. It has earned its place in popular film culture.');
INSERT INTO film_reviews (filmID, filmtitle, releasedate, rating, review) VALUES (20, 'Home Alone', '1990-11-16', 8, 'A festive comedy that pairs slapstick with real heart. Macaulay Culkin is irresistible as the resourceful kid, and the elaborate booby traps are gleefully inventive. The score adds Christmas magic, and the subplot with the neighbour gives it an emotional centre that keeps families returning every December. Still widely discussed.');
INSERT INTO film_reviews (filmID, filmtitle, releasedate, rating, review) VALUES (21, 'Edward Scissorhands', '1990-12-07', 8, 'A gentle, melancholy fairy tale from Tim Burton, with Johnny Depp wordless and wonderful as the gentle outsider. The pastel suburb contrasts beautifully with the gothic castle. It is funny, sad and visually inventive, and Danny Elfman''s music gives it an unforgettable dreamy tone. It remains a popular choice today.');
INSERT INTO film_reviews (filmID, filmtitle, releasedate, rating, review) VALUES (22, 'The Silence of the Lambs', '1991-02-14', 9, 'A taut, intelligent thriller powered by two extraordinary performances. Jodie Foster is quietly determined, while Anthony Hopkins makes every scene feel dangerous with barely a movement. The direction is controlled and suspenseful, and the final act is nail-biting. A genuine modern classic. Many people return to it again and again.');
INSERT INTO film_reviews (filmID, filmtitle, releasedate, rating, review) VALUES (23, 'Terminator 2: Judgment Day', '1991-07-03', 9, 'A rare sequel that expands its predecessor with spectacular action and surprising emotion. The liquid-metal effects remain astonishing, and Arnold Schwarzenegger''s protective machine is both funny and touching. Linda Hamilton is fierce, and the chase sequences are inventive, relentless and expertly staged. Many people return to it again and again.');
INSERT INTO film_reviews (filmID, filmtitle, releasedate, rating, review) VALUES (24, 'Beauty and the Beast', '1991-11-22', 9, 'Disney animation at its peak, with a heroine who loves books and songs that stay in your head for days. The ballroom scene is breathtaking, the supporting cast of talking furniture is delightful, and the story has genuine romance and warmth. Timeless and joyful. It remains a popular choice today.');
INSERT INTO film_reviews (filmID, filmtitle, releasedate, rating, review) VALUES (25, 'Unforgiven', '1992-08-07', 9, 'A thoughtful, weathered western that questions the legend of the gunfighter. Clint Eastwood plays an ageing man haunted by his past, and Gene Hackman is superb opposite him. The pacing is slow but purposeful, and the quiet, bleak finale feels earned and memorable. Whatever your taste, it leaves an impression.');
INSERT INTO film_reviews (filmID, filmtitle, releasedate, rating, review) VALUES (26, 'Groundhog Day', '1993-02-12', 10, 'A funny, surprisingly profound comedy about being stuck and learning to grow. Bill Murray is perfect as the grumpy weatherman, and the repeating structure never gets stale. It is warm, clever and moving, and it improves with every rewatch, which feels entirely appropriate. Whatever your taste, it leaves an impression.');
INSERT INTO film_reviews (filmID, filmtitle, releasedate, rating, review) VALUES (27, 'Jurassic Park', '1993-06-11', 9, 'Spielberg delivers wonder and terror in equal measure. The dinosaurs, a clever mix of animatronics and early digital effects, still look astonishing. The cast is charming, the scientific hook is irresistible, and the T. rex sequence in the rain is a masterclass in suspense. It remains a popular choice today.');
INSERT INTO film_reviews (filmID, filmtitle, releasedate, rating, review) VALUES (28, 'Mrs. Doubtfire', '1993-11-24', 7, 'Robin Williams is a whirlwind of invention in this warm family comedy. The disguise premise is silly, but his improvised energy and the heartfelt story about parents and children keep it grounded. Some jokes feel dated, yet the dinner-party chaos remains laugh-out-loud funny. Whatever your taste, it leaves an impression.');
INSERT INTO film_reviews (filmID, filmtitle, releasedate, rating, review) VALUES (29, 'The Lion King', '1994-06-24', 9, 'A majestic animated epic with Shakespearean undertones and unforgettable songs. The opening sequence is breathtaking, the villain is deliciously theatrical, and the emotional beats land powerfully. Hans Zimmer''s score gives it real grandeur, and it remains a joyful, moving experience for every generation. Whatever your taste, it leaves an impression.');
INSERT INTO film_reviews (filmID, filmtitle, releasedate, rating, review) VALUES (30, 'Forrest Gump', '1994-07-06', 8, 'A sweet, sentimental journey through decades of American history, anchored by Tom Hanks''s gentle performance. The effects blending him into old footage are clever, and the soundtrack is wonderful. It can feel too neat, but its warmth and heart are hard to resist. Whatever your taste, it leaves an impression.');
INSERT INTO film_reviews (filmID, filmtitle, releasedate, rating, review) VALUES (31, 'The Shawshank Redemption', '1994-09-23', 10, 'A story of patience, friendship and hope told with quiet confidence. Tim Robbins and Morgan Freeman have wonderful chemistry, and the narration gives the film a warm, literary feel. The ending is deeply satisfying. It rightly earns its reputation as one of the most beloved films ever. Still widely discussed.');
INSERT INTO film_reviews (filmID, filmtitle, releasedate, rating, review) VALUES (32, 'Pulp Fiction', '1994-10-14', 9, 'Tarantino''s fractured crime stories crackle with brilliant dialogue and unexpected humour. Every performance is memorable, from Travolta''s dancing to Samuel L. Jackson''s fierce monologues. The non-linear structure keeps surprising, and the soundtrack is superb. Violent and stylish, it changed independent cinema forever. Many people return to it again and again.');
INSERT INTO film_reviews (filmID, filmtitle, releasedate, rating, review) VALUES (33, 'Se7en', '1995-09-22', 8, 'A grim, rain-drenched thriller that stays with you. Morgan Freeman and Brad Pitt make a convincing odd pair of detectives, and the atmosphere is oppressive and stylish. The finale is bleak and shocking, so it is not for everyone, but the craftsmanship is undeniable. It remains a popular choice today.');
INSERT INTO film_reviews (filmID, filmtitle, releasedate, rating, review) VALUES (34, 'Toy Story', '1995-11-22', 10, 'The film that changed animation, and it still feels warm and clever. Woody and Buzz make a wonderful odd couple, the humour works for children and adults alike, and the story about jealousy and friendship is beautifully told. Remarkably, the groundbreaking visuals still look charming today. Still easy to enjoy.');
INSERT INTO film_reviews (filmID, filmtitle, releasedate, rating, review) VALUES (35, 'Heat', '1995-12-15', 8, 'A sprawling, serious crime epic with Robert De Niro and Al Pacino as mirror-image professionals. The downtown shootout is thunderously loud and brilliantly staged. At almost three hours it occasionally drifts, but the quiet conversations between the leads are the real highlight. Many people return to it again and again.');
INSERT INTO film_reviews (filmID, filmtitle, releasedate, rating, review) VALUES (36, 'Fargo', '1996-03-08', 9, 'A dark, deadpan comedy with a wonderfully gentle heroine at its centre. Frances McDormand is superb as the cheerful, pregnant police chief, and the snowy Minnesota landscape adds mood. It is funny, violent and oddly sweet, and the Coen brothers balance those tones perfectly. It remains a popular choice today.');
INSERT INTO film_reviews (filmID, filmtitle, releasedate, rating, review) VALUES (37, 'Independence Day', '1996-07-03', 6, 'Big, loud, silly and enormous fun if you accept it for what it is. The destruction scenes look spectacular, Will Smith is effortlessly charming, and the speeches are gloriously over the top. The plot has holes, but as summer blockbuster entertainment it delivers exactly what it promises. Still widely discussed.');
INSERT INTO film_reviews (filmID, filmtitle, releasedate, rating, review) VALUES (38, 'Men in Black', '1997-07-02', 7, 'A slick, silly sci-fi comedy with a brilliant premise. Will Smith and Tommy Lee Jones have great chemistry, the alien designs are playful, and the jokes come thick and fast. It is lightweight and a little rushed, but it is stylish, funny and consistently entertaining. Many viewers remember it fondly.');
INSERT INTO film_reviews (filmID, filmtitle, releasedate, rating, review) VALUES (39, 'Titanic', '1997-12-19', 8, 'A sweeping romance wrapped around a spectacular disaster. Kate Winslet and Leonardo DiCaprio are lovely together, and the recreation of the ship is astonishing. The dialogue can be clumsy, but the final hour is genuinely gripping, and the emotional scale remains impressive after all these years. Still easy to enjoy.');
INSERT INTO film_reviews (filmID, filmtitle, releasedate, rating, review) VALUES (40, 'The Big Lebowski', '1998-03-06', 9, 'A shaggy, endlessly quotable comedy where the plot barely matters because the characters are so wonderful. Jeff Bridges is perfectly relaxed as the Dude, and the supporting cast is hilarious. It gets funnier on every rewatch and has developed a devoted following for good reason. Many viewers remember it fondly.');
INSERT INTO film_reviews (filmID, filmtitle, releasedate, rating, review) VALUES (41, 'The Truman Show', '1998-06-05', 9, 'A clever, funny and surprisingly moving satire about living under constant observation. Jim Carrey shows impressive range, and the artificial town is wonderfully designed. The film feels even more relevant today, and its final scene is both uplifting and quietly thought-provoking. It has earned its place in popular film culture.');
INSERT INTO film_reviews (filmID, filmtitle, releasedate, rating, review) VALUES (42, 'Saving Private Ryan', '1998-07-24', 9, 'A powerful, immersive war film that opens with an unforgettable sequence of chaos and courage. Tom Hanks leads a believable squad, and the quieter moments are as affecting as the battles. It is intense, sincere and beautifully made, and it rewards viewers who are prepared for its seriousness. Worth seeing.');
INSERT INTO film_reviews (filmID, filmtitle, releasedate, rating, review) VALUES (43, 'The Matrix', '1999-03-31', 9, 'A thrilling blend of philosophy, kung fu and groundbreaking effects. Keanu Reeves makes a convincing reluctant hero, and the bullet-time sequences changed action cinema. The ideas are sometimes half-baked, but the style, pacing and sheer confidence make it a landmark science fiction film. Whatever your taste, it leaves an impression.');
INSERT INTO film_reviews (filmID, filmtitle, releasedate, rating, review) VALUES (44, 'The Sixth Sense', '1999-08-06', 8, 'A quiet, atmospheric ghost story with a sad heart. Haley Joel Osment is remarkable as a frightened child, and Bruce Willis is understated and sympathetic. The famous twist works because the film plays fair, and the second viewing reveals how carefully everything was constructed. It remains a popular choice today.');
INSERT INTO film_reviews (filmID, filmtitle, releasedate, rating, review) VALUES (45, 'Gladiator', '2000-05-05', 8, 'A muscular, old-fashioned epic with real emotional weight. Russell Crowe is magnetic as the fallen general, and Joaquin Phoenix is a deliciously petty emperor. The arena battles are visceral, Hans Zimmer''s music is rousing, and the story of loyalty and revenge is satisfyingly straightforward. It remains a popular choice today.');
INSERT INTO film_reviews (filmID, filmtitle, releasedate, rating, review) VALUES (46, 'Memento', '2001-03-16', 9, 'A cleverly structured thriller told largely in reverse, so we share the hero''s confusion. Guy Pearce is excellent as a man with no short-term memory, and the puzzle rewards close attention. It is a dazzling piece of storytelling that makes you want to watch it again immediately. Still widely discussed.');
INSERT INTO film_reviews (filmID, filmtitle, releasedate, rating, review) VALUES (47, 'Shrek', '2001-05-18', 8, 'A fairy-tale parody that is still sharp, funny and surprisingly sweet. Mike Myers, Eddie Murphy and Cameron Diaz make a lively trio, and the jokes work for children and adults. Some pop-culture references have aged, but the heart of the story remains charming and delightfully subversive. Still easy to enjoy.');
INSERT INTO film_reviews (filmID, filmtitle, releasedate, rating, review) VALUES (48, 'Spirited Away', '2001-07-20', 10, 'A breathtaking animated fantasy that feels like a dream you never want to end. Studio Ghibli fills every frame with imagination, from the strange bathhouse to the gentle river spirit. The heroine''s courage feels real, and the film is moving, funny and beautiful in equal measure. Still easy to enjoy.');
INSERT INTO film_reviews (filmID, filmtitle, releasedate, rating, review) VALUES (49, 'Harry Potter and the Philosopher''s Stone', '2001-11-16', 7, 'A warm, faithful introduction to a magical world. The young cast is charming, the sets are delightful, and John Williams''s theme is instantly memorable. It follows the book closely, so it can feel a little stiff, but the sense of wonder is genuine. Whatever your taste, it leaves an impression.');
INSERT INTO film_reviews (filmID, filmtitle, releasedate, rating, review) VALUES (50, 'The Lord of the Rings: The Fellowship of the Ring', '2001-12-19', 10, 'A beautifully crafted fantasy epic that makes Middle-earth feel real. The landscapes are spectacular, the cast is perfectly chosen, and Howard Shore''s score is magnificent. It balances warmth, humour and peril brilliantly, and the Mines of Moria sequence is a masterclass in escalating tension. It remains a popular choice today.');
INSERT INTO film_reviews (filmID, filmtitle, releasedate, rating, review) VALUES (51, 'Finding Nemo', '2003-05-30', 9, 'A gorgeous, funny and moving underwater adventure. Ellen DeGeneres steals scenes as the forgetful Dory, and the ocean has never looked so beautiful in animation. The story of an anxious father learning to let go gives the film real emotional depth. Pixar at its finest. Many viewers remember it fondly.');
INSERT INTO film_reviews (filmID, filmtitle, releasedate, rating, review) VALUES (52, 'Pirates of the Caribbean: The Curse of the Black Pearl', '2003-07-09', 8, 'A rollicking pirate adventure that nobody expected to be this much fun. Johnny Depp''s wobbly, wily Captain Jack is a delight, and the swashbuckling sequences are inventive. It runs a little long, but the humour, skeleton crew and Hans Zimmer''s energetic score keep things lively. Many viewers remember it fondly.');
INSERT INTO film_reviews (filmID, filmtitle, releasedate, rating, review) VALUES (53, 'Lost in Translation', '2003-09-12', 8, 'A gentle, melancholy film about two lonely people finding a brief connection in Tokyo. Bill Murray is wonderfully understated, and Scarlett Johansson is perfect opposite him. Very little happens, but the mood, humour and quiet ache of the ending linger long after the credits. It remains a popular choice today.');
INSERT INTO film_reviews (filmID, filmtitle, releasedate, rating, review) VALUES (54, 'Eternal Sunshine of the Spotless Mind', '2004-03-19', 9, 'A strange, tender romance about memory and loss. Jim Carrey is subdued and affecting, and Kate Winslet is wonderfully unpredictable. The inventive visuals feel handmade and dreamlike, and the story is surprisingly emotional. It rewards repeat viewing and stays with you for days. Whatever your taste, it leaves an impression.');
INSERT INTO film_reviews (filmID, filmtitle, releasedate, rating, review) VALUES (55, 'The Incredibles', '2004-11-05', 9, 'A stylish, witty superhero family adventure that handles action and domestic comedy equally well. The retro design is gorgeous, the characters are lovable, and the action sequences are inventive. It has real heart beneath the spectacle, and it remains one of Pixar''s most confident achievements. Many viewers remember it fondly.');
INSERT INTO film_reviews (filmID, filmtitle, releasedate, rating, review) VALUES (56, 'Batman Begins', '2005-06-15', 8, 'A grounded, serious reimagining that treats its hero as a real person. Christian Bale is convincing as both Bruce Wayne and Batman, and the supporting cast is superb. The fight scenes are choppy, but the origin story is compelling and the Gotham atmosphere is excellent. Many viewers remember it fondly.');
INSERT INTO film_reviews (filmID, filmtitle, releasedate, rating, review) VALUES (57, 'Little Miss Sunshine', '2006-07-26', 8, 'A warm, funny road movie about a dysfunctional family and a yellow minibus. The ensemble cast is wonderful, with Alan Arkin stealing every scene, and the humour is bittersweet. It is gentle, sharp and surprisingly uplifting, and the final talent show is both hilarious and touching. Still easy to enjoy.');
INSERT INTO film_reviews (filmID, filmtitle, releasedate, rating, review) VALUES (58, 'The Departed', '2006-10-06', 8, 'A fast, foul-mouthed and gripping crime thriller about two men living double lives. Leonardo DiCaprio and Matt Damon are strong, Jack Nicholson is gleefully menacing, and Scorsese keeps the tension high throughout. The plot twists get frantic late on, but it remains hugely entertaining. It remains a popular choice today.');
INSERT INTO film_reviews (filmID, filmtitle, releasedate, rating, review) VALUES (59, 'Pan''s Labyrinth', '2006-10-11', 9, 'A dark, beautiful fairy tale set against a brutal war. Guillermo del Toro''s creatures are strange, memorable and genuinely unsettling, and Ivana Baquero is wonderful as the young heroine. It is imaginative, moving and uncompromising, and its images stay with you long afterwards. Whatever your taste, it leaves an impression.');
INSERT INTO film_reviews (filmID, filmtitle, releasedate, rating, review) VALUES (60, 'Ratatouille', '2007-06-29', 9, 'A delicious, charming animated film about a rat who dreams of cooking. Paris looks gorgeous, the kitchen sequences are full of energy, and Anton Ego''s final review is moving. It is warm, funny and thoughtful, with a message about creativity that feels sincere rather than sugary. Still easy to enjoy.');
INSERT INTO film_reviews (filmID, filmtitle, releasedate, rating, review) VALUES (61, 'No Country for Old Men', '2007-11-09', 9, 'A tense, stripped-back thriller where silence speaks as loudly as violence. Javier Bardem is chilling, Tommy Lee Jones is wonderfully weary, and the Texan landscape feels vast and empty. The ending is deliberately unresolved, which frustrates some viewers but is thoroughly in keeping with the film''s mood. Still widely discussed.');
INSERT INTO film_reviews (filmID, filmtitle, releasedate, rating, review) VALUES (62, 'WALL-E', '2008-06-27', 9, 'A moving, almost wordless love story about a little robot on an abandoned Earth. The first half is a masterpiece of visual storytelling, and the second is charming, if more conventional. It is funny, beautiful and sad, with a gentle environmental message that never feels heavy-handed. Still easy to enjoy.');
INSERT INTO film_reviews (filmID, filmtitle, releasedate, rating, review) VALUES (63, 'The Dark Knight', '2008-07-18', 9, 'An ambitious, gripping crime epic disguised as a superhero film. Heath Ledger is mesmerising as the Joker, and Christian Bale is solid as the weary hero. It is long and occasionally overstuffed, but the tension, scale and moral questions make it a landmark of the genre. Still easy to enjoy.');
INSERT INTO film_reviews (filmID, filmtitle, releasedate, rating, review) VALUES (64, 'Slumdog Millionaire', '2008-11-12', 8, 'A vibrant, energetic story that uses a quiz show to explore a young man''s difficult life. Dev Patel is endearing, the Mumbai setting is vividly shot, and the soundtrack is exhilarating. Some of the plot is a little contrived, but the film''s warmth and momentum carry it through. Worth seeing.');
INSERT INTO film_reviews (filmID, filmtitle, releasedate, rating, review) VALUES (65, 'Up', '2009-05-29', 9, 'A funny, tender adventure that opens with one of the most moving sequences in animation. Carl and Russell make a delightful odd couple, and the floating house is a joy to watch. It is imaginative, warm and beautifully paced, and it will make you laugh and cry. Still widely discussed.');
INSERT INTO film_reviews (filmID, filmtitle, releasedate, rating, review) VALUES (66, 'District 9', '2009-08-14', 8, 'An inventive science fiction film that mixes documentary-style footage with action and sharp social commentary. Sharlto Copley is superb as an ordinary man pushed into extraordinary circumstances, and the visual effects are convincing and gritty. It turns more conventional in the final act, but it remains thrilling. Still widely discussed.');
INSERT INTO film_reviews (filmID, filmtitle, releasedate, rating, review) VALUES (67, 'Toy Story 3', '2010-06-18', 9, 'A funny, thrilling and unexpectedly emotional conclusion to the trilogy. The toys'' escape from the daycare is brilliantly staged, and the ending is a genuine tearjerker for anyone who grew up with the series. It balances nostalgia and fresh ideas with remarkable skill and affection. Many viewers remember it fondly.');
INSERT INTO film_reviews (filmID, filmtitle, releasedate, rating, review) VALUES (68, 'Inception', '2010-07-16', 9, 'A dazzling heist movie set inside dreams, full of ambition and spectacle. Leonardo DiCaprio leads a strong ensemble, the rotating corridor fight is astonishing, and Hans Zimmer''s score pounds. The exposition is heavy at times, but the final shot has fans debating it to this day. Still easy to enjoy.');
INSERT INTO film_reviews (filmID, filmtitle, releasedate, rating, review) VALUES (69, 'The Social Network', '2010-10-01', 9, 'A sharp, fast-moving drama about the birth of a tech giant. Aaron Sorkin''s dialogue crackles, Jesse Eisenberg is compelling as a driven, awkward founder, and David Fincher gives it a cool, polished look. It is smart, witty and surprisingly gripping for a story about computer code. Still easy to enjoy.');
INSERT INTO film_reviews (filmID, filmtitle, releasedate, rating, review) VALUES (70, 'The King''s Speech', '2010-11-26', 8, 'A warm, witty period drama about friendship and finding your voice. Colin Firth is superb as the reluctant king, and Geoffrey Rush is delightful as his unconventional therapist. It is traditional in style, but the performances and the gentle humour make it consistently engaging and moving. Still easy to enjoy.');
INSERT INTO film_reviews (filmID, filmtitle, releasedate, rating, review) VALUES (71, 'Drive', '2011-09-16', 8, 'A cool, stylish thriller that says a great deal with very little dialogue. Ryan Gosling is quietly magnetic, the neon-lit Los Angeles is gorgeous, and the electronic soundtrack is superb. It is violent in sudden bursts, and the slow pace will not suit everyone, but it is memorable. Worth seeing.');
INSERT INTO film_reviews (filmID, filmtitle, releasedate, rating, review) VALUES (72, 'The Avengers', '2012-05-04', 8, 'A joyful, crowd-pleasing team-up that makes juggling six heroes look easy. Robert Downey Jr. and Mark Ruffalo are standouts, the banter is sharp, and the New York battle is huge fun. It is not deep, but it is energetic, funny and thoroughly entertaining. Whatever your taste, it leaves an impression.');
INSERT INTO film_reviews (filmID, filmtitle, releasedate, rating, review) VALUES (73, 'Argo', '2012-10-12', 8, 'A tense, entertaining thriller based on an extraordinary true story. Ben Affleck directs with confidence, the period detail is excellent, and the final airport sequence is nail-biting. Some details are exaggerated for drama, but it is brisk, funny and gripping, with a great supporting cast. Many viewers remember it fondly.');
INSERT INTO film_reviews (filmID, filmtitle, releasedate, rating, review) VALUES (74, 'Skyfall', '2012-10-26', 7, 'A handsome, moody Bond film that looks beautiful and takes its hero''s age seriously. Daniel Craig is strong, Javier Bardem is gleefully theatrical, and Judi Dench gets a rich role. The third act in Scotland is atmospheric, even if the plot gets a little muddled. Many viewers remember it fondly.');
INSERT INTO film_reviews (filmID, filmtitle, releasedate, rating, review) VALUES (75, 'Gravity', '2013-10-04', 8, 'A visually breathtaking survival story set in orbit. Sandra Bullock carries the film with a strong, physical performance, and the long opening shot is astonishing. The script is simple and occasionally clunky, but the immersive sound and visuals make it a thrilling cinema experience. It remains a popular choice today.');
INSERT INTO film_reviews (filmID, filmtitle, releasedate, rating, review) VALUES (76, 'Frozen', '2013-11-27', 8, 'A bright, tuneful Disney musical about sisters rather than princes. The songs are catchy, the ice palace sequence is spectacular, and Olaf provides plenty of comic relief. The plot has a few bumpy moments, but the emotional core and gorgeous animation make it a worthy modern classic. Still widely discussed.');
INSERT INTO film_reviews (filmID, filmtitle, releasedate, rating, review) VALUES (77, 'Her', '2013-12-18', 8, 'A gentle, thoughtful science fiction romance set in a warm, pastel version of the near future. Joaquin Phoenix is wonderfully vulnerable, and Scarlett Johansson makes a voice feel entirely real. It is quiet, funny and melancholy, and it raises timely questions about technology and connection. Many viewers remember it fondly.');
INSERT INTO film_reviews (filmID, filmtitle, releasedate, rating, review) VALUES (78, 'The Grand Budapest Hotel', '2014-03-28', 9, 'A delightful, dollhouse-perfect comedy full of eccentric characters and precise visual gags. Ralph Fiennes is superb as the fussy concierge, and the pastel production design is a joy. Wes Anderson balances whimsy with real sadness, and the result is witty, charming and strangely moving. It remains a popular choice today.');
INSERT INTO film_reviews (filmID, filmtitle, releasedate, rating, review) VALUES (79, 'Guardians of the Galaxy', '2014-08-01', 8, 'A cheeky, colourful space adventure that feels refreshingly fun. Chris Pratt is likeable, Rocket and Groot steal every scene, and the retro soundtrack is a joy. The villain is forgettable, but the humour, warmth and chemistry of the ragtag team make it a thoroughly entertaining ride. Still easy to enjoy.');
INSERT INTO film_reviews (filmID, filmtitle, releasedate, rating, review) VALUES (80, 'Whiplash', '2014-10-10', 9, 'A white-knuckle drama about ambition and the cost of excellence. Miles Teller and J.K. Simmons are electric together, and the editing makes drumming feel like a fight scene. The ending is breathless, and the film raises tough questions about teaching and obsession without offering easy answers. Still easy to enjoy.');
INSERT INTO film_reviews (filmID, filmtitle, releasedate, rating, review) VALUES (81, 'Interstellar', '2014-11-07', 8, 'An ambitious, emotional space epic with spectacular visuals and a thundering organ score. Matthew McConaughey is strong, and the wormhole and black hole sequences are astonishing. The science-heavy exposition can be bumpy, but the father-daughter relationship gives the film real heart. It has earned its place in popular film culture.');
INSERT INTO film_reviews (filmID, filmtitle, releasedate, rating, review) VALUES (82, 'Mad Max: Fury Road', '2015-05-15', 9, 'A non-stop, spectacular chase film that is also astonishingly well made. Charlize Theron is formidable, the practical stunts are jaw-dropping, and the desert world is brilliantly designed. There is little dialogue and almost no downtime, which makes it a thrilling, exhausting and exhilarating ride. It remains a popular choice today.');
INSERT INTO film_reviews (filmID, filmtitle, releasedate, rating, review) VALUES (83, 'Inside Out', '2015-06-19', 9, 'A clever, colourful and deeply moving look at the emotions inside a young girl''s head. The idea is inventive, the humour works at several levels, and the message about sadness being valuable is beautifully delivered. Pixar combines imagination and heart in a way that few others can. Still widely discussed.');
INSERT INTO film_reviews (filmID, filmtitle, releasedate, rating, review) VALUES (84, 'The Martian', '2015-10-02', 8, 'A funny, optimistic survival story that celebrates problem-solving. Matt Damon is charming as the stranded astronaut, and the supporting cast is strong. Ridley Scott keeps the pace brisk, and the science feels plausible without being overwhelming. It is crowd-pleasing, intelligent and surprisingly light-hearted. Whatever your taste, it leaves an impression.');
INSERT INTO film_reviews (filmID, filmtitle, releasedate, rating, review) VALUES (85, 'Zootopia', '2016-03-04', 8, 'A clever, colourful animated comedy that doubles as a smart buddy-cop story. The animal city is wonderfully designed, the jokes land for all ages, and the leads have great chemistry. It handles its message about prejudice with a light touch, and it is consistently fun. Many viewers remember it fondly.');
INSERT INTO film_reviews (filmID, filmtitle, releasedate, rating, review) VALUES (86, 'Arrival', '2016-11-11', 9, 'A thoughtful, quietly moving science fiction story about communication and time. Amy Adams is superb as the linguist, and the alien design is striking and original. The pace is slow, but the emotional payoff is powerful, and the film rewards viewers who are willing to think. Still easy to enjoy.');
INSERT INTO film_reviews (filmID, filmtitle, releasedate, rating, review) VALUES (87, 'La La Land', '2016-12-09', 8, 'A joyful, colourful musical that celebrates dreamers and the cost of chasing dreams. Ryan Gosling and Emma Stone are charming together, the opening number is dazzling, and the ending is bittersweet. The songs are more gentle than showy, but the romance and visual style are lovely. Still easy to enjoy.');
INSERT INTO film_reviews (filmID, filmtitle, releasedate, rating, review) VALUES (88, 'Dunkirk', '2017-07-21', 8, 'A tense, immersive war film that focuses on survival rather than speeches. The interwoven timelines build suspense, the aerial scenes are spectacular, and Hans Zimmer''s ticking score keeps your nerves on edge. Character development is minimal, but the experience is intense, precise and impressively staged. Many viewers remember it fondly.');
INSERT INTO film_reviews (filmID, filmtitle, releasedate, rating, review) VALUES (89, 'Blade Runner 2049', '2017-10-06', 8, 'A beautiful, slow, contemplative sequel that respects the original while finding its own voice. Ryan Gosling is quietly effective, and Roger Deakins''s cinematography is stunning. It is long and deliberately paced, but the visuals, sound design and big ideas make it a remarkable piece of science fiction. Still widely discussed.');
INSERT INTO film_reviews (filmID, filmtitle, releasedate, rating, review) VALUES (90, 'Coco', '2017-11-22', 9, 'A vibrant, heartfelt celebration of family and memory set during the Day of the Dead. The animation is gorgeous, the songs are catchy, and the emotional finale is guaranteed to bring a tear. It is warm, funny and beautifully made, and it honours its culture with real care. Worth seeing.');
INSERT INTO film_reviews (filmID, filmtitle, releasedate, rating, review) VALUES (91, 'Black Panther', '2018-02-16', 8, 'A confident, colourful superhero film with a richly imagined setting. Chadwick Boseman is dignified and strong, and the supporting cast, especially Letitia Wright, is wonderful. The villain has real depth, the costumes are spectacular, and the film feels fresh, energetic and culturally significant. Whatever your taste, it leaves an impression.');
INSERT INTO film_reviews (filmID, filmtitle, releasedate, rating, review) VALUES (92, 'Spider-Man: Into the Spider-Verse', '2018-12-14', 9, 'A dazzling, inventive animated film that looks like a living comic book. Miles Morales is a lovable hero, the humour is sharp, and the multiverse premise is handled with clarity. The visual style is unlike anything before it, and the emotional core makes it a joy. Still easy to enjoy.');
INSERT INTO film_reviews (filmID, filmtitle, releasedate, rating, review) VALUES (93, 'Parasite', '2019-05-30', 9, 'A razor-sharp, darkly funny thriller about two families on opposite sides of a wealth divide. Bong Joon-ho controls the tone brilliantly, shifting from comedy to tension without a wasted scene. The house is a character in its own right, and the ending is unforgettable. It remains a popular choice today.');
INSERT INTO film_reviews (filmID, filmtitle, releasedate, rating, review) VALUES (94, 'Knives Out', '2019-11-27', 8, 'A fun, twisty modern whodunnit with a glorious ensemble cast. Daniel Craig has a wonderful time with his Southern drawl, Ana de Armas is excellent, and the mansion setting is delightfully cluttered. The script is witty, clever and full of satisfying surprises, and it respects the genre. Still widely discussed.');
INSERT INTO film_reviews (filmID, filmtitle, releasedate, rating, review) VALUES (95, '1917', '2019-12-25', 8, 'A tense, technically astonishing war film staged as though it were one continuous shot. George MacKay is excellent as the young soldier on a desperate mission, and the cinematography is breathtaking. The story is simple, but the immersive style makes it feel urgent, personal and intense. Still easy to enjoy.');
INSERT INTO film_reviews (filmID, filmtitle, releasedate, rating, review) VALUES (96, 'Soul', '2020-12-25', 8, 'A warm, thoughtful Pixar film about finding meaning in the small moments of life. The jazz soundtrack is wonderful, the afterlife designs are imaginative, and Jamie Foxx brings real warmth. It can feel a little abstract, but it is funny, moving and beautifully animated. It remains a popular choice today.');
INSERT INTO film_reviews (filmID, filmtitle, releasedate, rating, review) VALUES (97, 'Dune', '2021-10-22', 8, 'A grand, serious science fiction epic with spectacular desert landscapes and thunderous sound design. Timothée Chalamet is thoughtful as the reluctant heir, and the supporting cast is strong. It ends as the first half of the story, but it looks and sounds magnificent. Whatever your taste, it leaves an impression.');
INSERT INTO film_reviews (filmID, filmtitle, releasedate, rating, review) VALUES (98, 'Everything Everywhere All at Once', '2022-03-25', 9, 'A wildly inventive, funny and unexpectedly moving multiverse adventure. Michelle Yeoh is brilliant, the fight scenes are creative, and the film shifts from absurd comedy to genuine heartbreak without losing its balance. It is chaotic, ambitious and overflowing with imagination, and well worth the ride. Many viewers remember it fondly.');
INSERT INTO film_reviews (filmID, filmtitle, releasedate, rating, review) VALUES (99, 'Top Gun: Maverick', '2022-05-27', 8, 'A rare legacy sequel that actually improves on the original. The aerial sequences are astonishingly real, Tom Cruise is still charismatic, and Miles Teller brings emotional weight. It is polished, sentimental and thrilling, with a final mission that will have you gripping your seat. It remains a popular choice today.');
INSERT INTO film_reviews (filmID, filmtitle, releasedate, rating, review) VALUES (100, 'Oppenheimer', '2023-07-21', 8, 'A dense, ambitious biographical drama with an outstanding central performance from Cillian Murphy. Christopher Nolan weaves timelines together with confidence, and the sound design is overwhelming. It is long and talky, but the cast is superb and the tension in the final act is remarkable. Many viewers remember it fondly.');
